package de.meiapps.meicraft;

import android.app.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import android.util.AtomicFile;
import java.io.*;
import java.util.concurrent.*;

public final class MainActivity extends Activity {
 GameView game;UpdateController updates;volatile World world;AtomicFile file;volatile int slot;volatile boolean paused;
 final ExecutorService disk=Executors.newSingleThreadExecutor();final Handler handler=new Handler(Looper.getMainLooper());
 final Runnable autosave=new Runnable(){public void run(){save();handler.postDelayed(this,30000);}};
 AtomicFile slotFile(int mode){return new AtomicFile(new File(getFilesDir(),mode==1?"story.mcworld":"world.mcworld"));}
 World load(AtomicFile source,int mode,boolean[] recovered){
  try{World loaded=World.decode(source.readFully());if(loaded.story!=(mode==1))throw new IOException("Wrong world slot");return loaded;}
  catch(Exception e){recovered[0]=source.getBaseFile().exists();if(recovered[0])try{java.nio.file.Files.copy(source.getBaseFile().toPath(),new File(getFilesDir(),source.getBaseFile().getName()+"-damaged-"+System.currentTimeMillis()).toPath());}catch(IOException ignored){}return new World(20261025L+mode,mode==1);}
 }
 @Override public void onCreate(Bundle state){super.onCreate(state);slot=getSharedPreferences("worlds",0).getInt("active",0)==1?1:0;file=slotFile(slot);boolean[] recovered={false};world=load(file,slot,recovered);
  game=new GameView(this,world);setContentView(game.root);updates=new UpdateController(this);immersive();
  if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::menu);
  if(recovered[0])new AlertDialog.Builder(this).setTitle("Spielstand nicht lesbar").setMessage("Die alte Datei wurde als Sicherung behalten. Eine neue Welt wurde geöffnet.").setPositiveButton("OK",null).show();
  if(!getPreferences(0).getBoolean("introduced",false))new AlertDialog.Builder(this).setTitle("Willkommen bei meiCraft").setMessage("Links bewegen, rechts wischen zum Umsehen. Mit − abbauen, mit + bauen. Über STORY kannst du zwischen Kreativwelt und Story wechseln. Beide Welten speichern getrennt.").setPositiveButton("Losbauen",(d,w)->getPreferences(0).edit().putBoolean("introduced",true).apply()).show();
 }
 void immersive(){if(Build.VERSION.SDK_INT>=30){WindowInsetsController c=getWindow().getInsetsController();if(c!=null){c.hide(WindowInsets.Type.systemBars());c.setSystemBarsBehavior(WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);}}else immersiveLegacy();}
 // Android 8–10 have no WindowInsetsController; use their supported fullscreen API.
 @SuppressWarnings("deprecation") private void immersiveLegacy(){getWindow().getDecorView().setSystemUiVisibility(5894);}
 void save(){if(world==null||file==null||disk.isShutdown())return;final byte[] data;final AtomicFile destination=file;final World snapshot=world;try{synchronized(snapshot){data=snapshot.encode();}}catch(IOException e){toast("Speichern fehlgeschlagen");return;}
  disk.execute(()->{FileOutputStream stream=null;try{stream=destination.startWrite();stream.write(data);destination.finishWrite(stream);}catch(IOException e){if(stream!=null)destination.failWrite(stream);runOnUiThread(()->toast("Spielstand konnte nicht gespeichert werden"));}});
 }
 void switchMode(int target){if(target==slot){paused=false;return;}paused=true;game.clearInput();save();AtomicFile destination=slotFile(target);
  disk.execute(()->{boolean[] recovered={false};World next=load(destination,target,recovered);runOnUiThread(()->{if(isFinishing()||isDestroyed())return;game.gl.queueEvent(()->{game.replace(next);runOnUiThread(()->{if(isFinishing()||isDestroyed())return;world=next;file=destination;slot=target;getSharedPreferences("worlds",0).edit().putInt("active",slot).apply();paused=false;save();if(recovered[0])toast("Beschädigter Spielstand als Sicherung behalten");if(next.story&&!getPreferences(0).getBoolean("storyIntroduced",false)){getPreferences(0).edit().putBoolean("storyIntroduced",true).apply();chapter();}});});});});
 }
 void chooseMode(){paused=true;game.clearInput();new AlertDialog.Builder(this).setTitle("Weltmodus wechseln").setItems(new String[]{"Kreativ · Freies Bauen","Story · Sammeln und Werkzeuge"},(d,n)->switchMode(n)).setOnCancelListener(d->paused=false).show();}
 void menu(){if(paused)return;paused=true;game.clearInput();new AlertDialog.Builder(this).setTitle("meiCraft · "+(world.story?"Story":"Kreativ")).setItems(new String[]{"Weiterbauen","Baumaterial wählen",world.story?"Laufmodus · Story":world.flying?"Laufen statt fliegen":"Fliegen statt laufen","Spielstand speichern","Neue Welt …","Steuerung","Updates","Weltmodus wechseln",world.story?"Story und Werkbank":"Storymodus entdecken"},(d,n)->{
  paused=false;switch(n){case 1:handler.post(this::palette);break;case 2:if(world.story)toast("Im Storymodus läufst und springst du. ↑ hilft auch im Wasser.");else{synchronized(world){world.flying=!world.flying;}game.velocityY=0;}break;case 3:save();toast("Speichern gestartet");break;case 4:handler.post(this::newWorld);break;case 5:handler.post(this::help);break;case 6:handler.post(updates::settings);break;case 7:handler.post(this::chooseMode);break;case 8:handler.post(world.story?this::storyMenu:this::chooseMode);break;default:break;}
 }).setOnDismissListener(d->paused=false).show();}
 void help(){paused=true;game.clearInput();new AlertDialog.Builder(this).setTitle("Steuerung").setMessage("Links am Kreis bewegen, rechts wischen zum Umsehen. Mit + setzt du den ausgewählten Block neben den anvisierten Block.\n\nStory: − zum Abbauen gedrückt halten. Du brauchst passende Werkzeuge und gesammelte Materialien. Gras gibt Erde. Unter STORY findest du Mikos Aufträge und Rezepte. Baue Stufen aus gesammelten Blöcken, um Gruben zu verlassen.\n\n↑ springt oder schwimmt aufwärts. In der Kreativwelt kannst du zusätzlich fliegen. Jede Welt speichert separat, alle 30 Sekunden und beim Verlassen. Zum Spielen ist kein Internet nötig.").setPositiveButton("Verstanden",null).setOnDismissListener(d->paused=false).show();}
 void palette(){paused=true;game.clearInput();String[] names=new String[World.NAMES.length-1];synchronized(world){for(int i=1;i<World.NAMES.length;i++)names[i-1]=World.NAMES[i]+(world.story?" · "+world.progress.inventory[i]:"");}new AlertDialog.Builder(this).setTitle("Baumaterial").setItems(names,(d,n)->{synchronized(world){world.selected=n+1;}paused=false;}).setOnCancelListener(d->paused=false).show();}
 String[] storyRows(){synchronized(world){return new String[]{"Auftrag: "+world.progress.goal(),"4 Bretter · 1 Holz (Vorrat: "+world.progress.inventory[9]+")","4 Ziegel · 4 Erde + 1 Stein (Vorrat: "+world.progress.inventory[7]+")","2 Glas · 2 Sand + 1 Holz (Vorrat: "+world.progress.inventory[8]+")","1 Eisenbarren · 1 Erz + 1 Holz (Vorrat: "+world.progress.iron+")","1 Eisenblock · 9 Barren (Vorrat: "+world.progress.inventory[14]+")","4 Grasblöcke · 4 Erde + 1 Laub"};}}
 void storyMenu(){if(!world.story)return;paused=true;game.clearInput();ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,new java.util.ArrayList<>(java.util.Arrays.asList(storyRows())));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Story · Werkbank / Ofen").setAdapter(adapter,null).setNegativeButton("Weiterbauen",null).setOnDismissListener(d->paused=false).create();dialog.show();dialog.getListView().setOnItemClickListener((parent,view,position,id)->{if(position==0){dialog.dismiss();handler.post(this::chapter);return;}String result;synchronized(world){result=world.progress.craft(position-1);}toast(result);save();adapter.setNotifyOnChange(false);adapter.clear();adapter.addAll(storyRows());adapter.notifyDataSetChanged();});}
 void chapter(){if(!world.story)return;paused=true;game.clearInput();String title,detail;boolean ready;synchronized(world){title=world.progress.title();detail=world.progress.detail();ready=world.progress.ready();}final boolean claimable=ready;new AlertDialog.Builder(this).setTitle(title).setMessage(detail).setPositiveButton(ready?"Auftrag abschließen":"Weiter sammeln",(d,n)->{if(claimable){synchronized(world){world.progress.claim();}save();handler.post(this::chapter);}}).setNeutralButton("Werkbank",(d,n)->handler.post(this::storyMenu)).setOnDismissListener(d->paused=false).show();}
 void newWorld(){paused=true;game.clearInput();EditText seed=new EditText(this);seed.setSingleLine(true);seed.setHint("Weltname oder Zahl (optional)");new AlertDialog.Builder(this).setTitle("Neue "+(world.story?"Storywelt":"Kreativwelt")+"?").setMessage("Nur die aktuelle Welt wird ersetzt. Die andere Welt bleibt erhalten. Das Ersetzen kann nicht rückgängig gemacht werden.").setView(seed).setPositiveButton("Neue Welt",(d,n)->{String text=seed.getText().toString().trim();long value=text.isEmpty()?System.currentTimeMillis():text.hashCode();try{value=Long.parseLong(text);}catch(NumberFormatException ignored){}World next=new World(value,slot==1);game.gl.queueEvent(()->{game.replace(next);runOnUiThread(()->{if(isFinishing()||isDestroyed())return;world=next;paused=false;save();if(next.story)chapter();});});}).setNegativeButton("Abbrechen",(d,n)->paused=false).setOnCancelListener(d->paused=false).show();}
 void toast(String text){Toast.makeText(this,text,Toast.LENGTH_SHORT).show();}
 @Override protected void onResume(){super.onResume();if(updates!=null)updates.onResume();if(game!=null)game.gl.onResume();handler.removeCallbacks(autosave);handler.postDelayed(autosave,30000);immersive();}
 @Override protected void onPause(){if(updates!=null)updates.onPause();if(game!=null){game.clearInput();game.gl.onPause();}save();handler.removeCallbacks(autosave);super.onPause();}
 @Override protected void onDestroy(){if(updates!=null)updates.onDestroy();handler.removeCallbacks(autosave);disk.shutdown();super.onDestroy();}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(!focused&&game!=null)game.clearInput();}
 @Override public boolean onKeyUp(int code,KeyEvent event){if(Build.VERSION.SDK_INT<33&&code==KeyEvent.KEYCODE_BACK){menu();return true;}return super.onKeyUp(code,event);}
}
